1	package main
2	
3	import (
4		"errors"
5		"os"
6		"strings"
7	)
8	
9	func main() {
10		if err := Execute(); err != nil {
11			os.Exit(exitCode(err))
12		}
13	}
14	
15	// exitCode maps errors to Unix-style exit codes.
16	//
17	//	0 — success
18	//	1 — runtime error
19	//	2 — usage error (invalid flags, arguments, or missing required input)
20	func exitCode(err error) int {
21		if err == nil {
22			return 0
23		}
24		var ue *usageError
25		if errors.As(err, &ue) {
26			return 2
27		}
28		// Cobra's built-in flag/argument errors don't wrap a typed error,
29		// so we fall back to message prefix detection for those.
30		if isCobraUsageError(err) {
31			return 2
32		}
33		return 1
34	}
35	
36	// isCobraUsageError detects Cobra-generated flag and argument errors
37	// that should map to exit code 2. These are errors from Cobra itself,
38	// not from our RunE functions (which should use usageError).
39	func isCobraUsageError(err error) bool {
40		msg := err.Error()
41		prefixes := []string{
42			"unknown command",
43			"unknown flag",
44			"invalid argument",
45			"accepts ",
46			"requires ",
47			"required flag(s)",
48			"at least one of the flags",
49		}
50		for _, p := range prefixes {
51			if strings.HasPrefix(msg, p) {
52				return true
53			}
54		}
55		return false
56	}
