var intRunOpts intRunFlags

var intRunCmd = &cobra.Command{
	Use:   "run [dir]",
	Short: "Launch the local integration dashboard",
	Long: "Start a local web dashboard that visualizes the integrations scaffolded under dir " +
		"(default: the current directory) — their template, pinned source, version, and scaffold values. " +
		"The dashboard is served from the CLI itself and opens in your browser; it does not start any " +
