// Types mirror the Go JSON contract served by `intropy int run`
// (internal/dashboard). Integration matches template.ScaffoldEntry;
// IntegrationDetail adds the best-effort on-disk enrichment.

export interface Integration {
  path: string
  schemaVersion: number
  template: string
  owner: string
  repo: string
  version: string
  values: Record<string, unknown>
}

export interface FileDoc {
  name: string
  content: string
}

export interface IntegrationDetail extends Integration {
  agents?: FileDoc
  readme?: FileDoc
  daprComponents?: string[]
  pipelineSteps?: string[]
}

export interface Health {
  status: string
  version: string
}

async function getJSON<T>(url: string): Promise<T> {
  const res = await fetch(url)
  if (!res.ok) {
    let message = `${res.status} ${res.statusText}`
    try {
      const body = (await res.json()) as { error?: string }
      if (body?.error) message = body.error
    } catch {
      // response had no JSON error body; keep the status line
    }
    throw new Error(message)
  }
  return (await res.json()) as T
}

export const api = {
  listIntegrations: () => getJSON<Integration[]>('/api/integrations'),
  getIntegration: (path: string) =>
    getJSON<IntegrationDetail>(`/api/integrations/${path}`),
  health: () => getJSON<Health>('/api/health'),
}

import { useEffect, useState } from 'react'
import { api, type Integration, type IntegrationDetail } from './api'
import { Sidebar } from './components/Sidebar'
import { DetailPanel } from './components/DetailPanel'

export default function App() {
  const [integrations, setIntegrations] = useState<Integration[] | null>(null)
  const [selected, setSelected] = useState<string | null>(null)
  const [detail, setDetail] = useState<IntegrationDetail | null>(null)
  const [version, setVersion] = useState<string>('')
  const [error, setError] = useState<string | null>(null)

  useEffect(() => {
    api
      .listIntegrations()
      .then(setIntegrations)
      .catch((e: unknown) => setError(errText(e)))
    api
      .health()
      .then((h) => setVersion(h.version))
      .catch(() => {})
  }, [])

  // Auto-select the first integration once the list loads.
  useEffect(() => {
    if (integrations && integrations.length > 0 && !selected) {
      setSelected(integrations[0].path)
    }
  }, [integrations, selected])

  useEffect(() => {
    if (!selected) {
      setDetail(null)
      return
    }
    setDetail(null)
    api
      .getIntegration(selected)
      .then(setDetail)
      .catch((e: unknown) => setError(errText(e)))
  }, [selected])

  return (
    <div className="app">
      <header className="topbar">
        <div className="brand">
          <span className="brand-mark" aria-hidden />
          <span className="brand-name">Intropy</span>
          <span className="brand-sub">dashboard</span>
        </div>
        {version && <span className="version">{version}</span>}
      </header>

      <div className="layout">
        <Sidebar
          integrations={integrations}
          selected={selected}
          onSelect={setSelected}
        />
        <main className="content">
          {error && <div className="banner error">{error}</div>}
          <DetailPanel detail={detail} hasSelection={!!selected} />
        </main>
      </div>
    </div>
  )
}

function errText(e: unknown): string {
  return e instanceof Error ? e.message : String(e)
}

import type { Integration } from '../api'

interface Props {
  integrations: Integration[] | null
  selected: string | null
  onSelect: (path: string) => void
}

export function Sidebar({ integrations, selected, onSelect }: Props) {
  return (
    <aside className="sidebar">
      <div className="sidebar-header">
        Integrations
        {integrations && <span className="count">{integrations.length}</span>}
      </div>

      {integrations === null && <p className="muted pad">Loading…</p>}

      {integrations?.length === 0 && (
        <p className="muted pad">No scaffolded integrations found.</p>
      )}

      <ul className="int-list">
        {integrations?.map((it) => (
          <li key={it.path}>
            <button
              className={'int-item' + (it.path === selected ? ' active' : '')}
              onClick={() => onSelect(it.path)}
            >
              <span className="int-name">{integrationName(it)}</span>
              <span className="int-path">{it.path}</span>
            </button>
          </li>
        ))}
      </ul>
    </aside>
  )
}

// integrationName prefers the scaffold's human name, then its appId, then the
// directory path as a last resort.
function integrationName(it: Integration): string {
  const values = it.values ?? {}
  return (
    (values.name as string) || (values.appId as string) || it.path
  )
}

import type { ReactNode } from 'react'
import type { IntegrationDetail } from '../api'

interface Props {
  detail: IntegrationDetail | null
  hasSelection: boolean
}

export function DetailPanel({ detail, hasSelection }: Props) {
  if (!hasSelection) {
    return <p className="empty">Select an integration to see its details.</p>
  }
  if (!detail) {
    return <p className="empty">Loading…</p>
  }

  const values = Object.entries(detail.values ?? {})

  return (
    <article className="detail">
      <h1 className="detail-title">{title(detail)}</h1>

      <div className="meta-grid">
        <Meta label="Template" value={detail.template || '—'} />
        <Meta label="Version" value={detail.version} />
        <Meta label="Source" value={`${detail.owner}/${detail.repo}`} />
        <Meta label="Path" value={detail.path} />
      </div>

      <Section title="Values">
        {values.length === 0 ? (
          <p className="muted">No scaffold values.</p>
        ) : (
          <table className="kv">
            <tbody>
              {values.map(([k, v]) => (
                <tr key={k}>
                  <th>{k}</th>
                  <td>{String(v)}</td>
                </tr>
              ))}
            </tbody>
          </table>
        )}
      </Section>

      {detail.pipelineSteps && detail.pipelineSteps.length > 0 && (
        <Section title="Pipeline steps">
          <ol className="steps">
            {detail.pipelineSteps.map((s) => (
              <li key={s}>{stepName(s)}</li>
            ))}
          </ol>
        </Section>
      )}

      {detail.daprComponents && detail.daprComponents.length > 0 && (
        <Section title="Dapr components">
          <ul className="chips">
            {detail.daprComponents.map((c) => (
              <li key={c} className="chip">
                {c}
              </li>
            ))}
          </ul>
        </Section>
      )}

      {detail.readme && (
        <Section title={detail.readme.name}>
          <pre className="doc">{detail.readme.content}</pre>
        </Section>
      )}
    </article>
  )
}

function Meta({ label, value }: { label: string; value: string }) {
  return (
    <div className="meta">
      <span className="meta-label">{label}</span>
      <span className="meta-value">{value}</span>
    </div>
  )
}

function Section({ title, children }: { title: string; children: ReactNode }) {
  return (
    <section className="section">
      <h2 className="section-title">{title}</h2>
      {children}
    </section>
  )
}

function title(detail: IntegrationDetail): string {
  const values = detail.values ?? {}
  return (values.name as string) || (values.appId as string) || detail.path
}

// stepName turns a source filename like "OrderValidateStep.cs" into a readable
// "Order Validate".
function stepName(file: string): string {
  return file
    .replace(/\.[^.]+$/, '')
    .replace(/Step$/, '')
    .replace(/([a-z])([A-Z])/g, '$1 $2')
}

