import type { Integration } from '../api'

interface Props {
  integrations: Integration[] | null
  selected: string | null
  onSelect: (path: string) => void
  collapsed: boolean
  onToggle: () => void
}

export function Sidebar({
  integrations,
  selected,
  onSelect,
  collapsed,
  onToggle,
}: Props) {
  return (
    <aside className={'sidebar' + (collapsed ? ' collapsed' : '')}>
      <div className="sidebar-header">
        {!collapsed && (
          <span className="sidebar-title">
            Integrations
            {integrations && <span className="count">{integrations.length}</span>}
          </span>
        )}
        <button
          className="collapse-btn"
          onClick={onToggle}
          aria-label={collapsed ? 'Expand sidebar' : 'Collapse sidebar'}
          aria-expanded={!collapsed}
          title={collapsed ? 'Expand sidebar' : 'Collapse sidebar'}
        >
          {collapsed ? '»' : '«'}
        </button>
      </div>

      {!collapsed && integrations === null && (
        <p className="muted pad">Loading…</p>
      )}

      {!collapsed && integrations?.length === 0 && (
        <p className="muted pad">No scaffolded integrations found.</p>
      )}

      <ul className="int-list">
        {integrations?.map((it) => {
          const name = integrationName(it)
          const active = it.path === selected
          return (
            <li key={it.path}>
              <button
                className={'int-item' + (active ? ' active' : '')}
                onClick={() => onSelect(it.path)}
                title={collapsed ? `${name} — ${it.path}` : undefined}
              >
                {collapsed ? (
                  <span className="int-initial">{initial(name)}</span>
                ) : (
                  <>
                    <span className="int-name">{name}</span>
                    <span className="int-path">{it.path}</span>
                  </>
                )}
              </button>
            </li>
          )
        })}
      </ul>
    </aside>
  )
}

// integrationName prefers the scaffold's human name, then its appId, then the
// directory path as a last resort.
function integrationName(it: Integration): string {
  const values = it.values ?? {}
  return (values.name as string) || (values.appId as string) || it.path
}

function initial(name: string): string {
  return name.trim().charAt(0).toUpperCase() || '?'
}

